class Component extends DCLogic {
  componentDidMount(){ const go=()=>window.SWD?SWD.ready(()=>this.init()):setTimeout(go,30); go(); }
  init(){
    const D=SW_DEMO_DATA, CF=SW_DEMO, $=id=>document.getElementById(id), UF=SWD.UFS(), S=SW_GEO.states, MG=D.mig;
    SWD.page({active:'mig',lv:'BR',label:'Migração'});
    $('vstamp').innerHTML=SWD.stamp('mig'); $('src').innerHTML=SWD.srcLine(['mig']);
    const st={d:'in',sel:SWD.q.get('u')||'SP',hov:null};
    SWD.seg($('dir'),[['in','De onde vieram os moradores','De onde vieram'],['out','Para onde foram os nascidos aqui','Para onde foram']],st.d,k=>{st.d=k;draw()},'Direção');
    $('place').innerHTML=UF.slice().sort((a,b)=>SWD.name(a).localeCompare(SWD.name(b))).map(u=>`<option value="${u}">${SWD.name(u)}</option>`).join('');
    $('place').onchange=e=>{st.sel=e.target.value;draw()};
    const map=new SW.Map($('map'),{aria:'Mapa de migração entre estados',onHover:u=>{st.hov=u;draw()},onClick:u=>{st.sel=u;draw()}});
    const svg=map.svg, arcs=document.createElementNS('http://www.w3.org/2000/svg','g'); svg.insertBefore(arcs,svg.querySelector('.hov'));
    const inn=u=>UF.filter(o=>o!==u).map(o=>[o,MG[u][o]||0]), out=u=>UF.filter(d=>d!==u).map(d=>[d,MG[d][u]||0]);
    const sum=a=>a.reduce((s,x)=>s+x[1],0);
    const arc=(a,b,w)=>{ const [x0,y0]=S[a].c,[x1,y1]=S[b].c, mx=(x0+x1)/2, my=(y0+y1)/2, dx=x1-x0, dy=y1-y0, k=.22; return `<path class="arc${st.d==='out'?' out':''}" d="M${x0} ${y0}Q${mx-dy*k} ${my+dx*k} ${x1} ${y1}" style="stroke-width:${w.toFixed(1)}"/>`; };
    const draw=()=>{ const u=st.sel, h=st.hov, f=st.d==='in'?inn(u):out(u), top=f.slice().sort((a,b)=>b[1]-a[1]).slice(0,8), mx=top[0][1];
      $('place').value=u;
      map.update({fill:v=>v===u?{f:'var(--accent)',k:5}:top.some(t=>t[0]===v)?{f:'var(--g1)',k:0}:{f:'var(--g0)',k:0}});
      map.mark(u,h);
      arcs.innerHTML=top.slice().reverse().map(([o,v])=>st.d==='in'?arc(o,u,1+v/mx*9):arc(u,o,1+v/mx*9)).join('')+top.map(([o])=>`<circle cx="${S[o].c[0]}" cy="${S[o].c[1]}" r="3" style="fill:${st.d==='in'?'var(--accent)':'var(--d0)'};pointer-events:none"/>`).join('');
      $('vt').textContent=st.d==='in'?`Moradores de ${SWD.name(u)} nascidos em outro estado`:`Nascidos em ${SWD.name(u)} que moram em outro estado`;
      $('lg').innerHTML=`<span><i class="ln" style="border-color:${st.d==='in'?'var(--accent)':'var(--d0)'};border-top-width:4px"></i>Os 8 maiores fluxos; espessura proporcional ao número de pessoas</span>`;
      const I=sum(inn(u)), O=sum(out(u)), T=MG[u].T, bal=I-O;
      $('card').innerHTML=`<div class="card" aria-live="polite"><div class="meta">${SWD.region(u)}</div><div class="nm">${SWD.name(u)}</div>
        <div class="facts"><div class="fact"><span>Moradores nascidos em outro estado</span><b>${SWD.mi(I)} · ${SWD.pct(I/T*100,1)}</b></div>
        <div class="fact"><span>Nascidos aqui que moram em outro estado</span><b>${SWD.mi(O)}</b></div>
        <div class="fact"><span>Diferença entre os dois</span><b>${bal>=0?'+':'−'}${SWD.mi(Math.abs(bal))}</b></div>
        <div class="fact"><span>Moradores nascidos em outro país</span><b>${SWD.mi(MG[u].EXT)}</b></div></div><div style="margin-top:4px">${SWD.stamp('mig')}</div></div>`;
      $('lh').textContent=st.d==='in'?'Estados de nascimento':'Estados onde moram';
      $('list').innerHTML=top.map(([o,v])=>`<div><span style="white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${SWD.name(o)}</span><span class="bar"><i style="width:${v/mx*100}%;background:${st.d==='in'?'var(--accent)':'var(--d0)'}"></i></span><b>${SWD.mi(v,true)}</b></div>`).join('');
    };
    draw();
  }
  renderVals(){ return {}; }
}
